sql.where:
r.create_time < #{endTime}
and r.create_time >= #{startTime}
and r.user_id = #{userId}
and r.process_id = #{processId}
and r.item_code = #{itemCode}

    and (

        r.user_id in #{id} or

    r.user_name like concat('%', #{accountKeyword}, '%')
    or r.nick_name like concat('%', #{accountKeyword}, '%')
    )
